213	
214	
215	    /**
216	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
217	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
218	     * Validation already rejects {@code null} values and the pattern-constrained fields
219	     * when blank, but {@code address} and {@code city} have no pattern, so a
220	     * whitespace-only value would otherwise slip through.
221	     *
222	     * @param ownerFieldsDto the submitted owner fields
223	     * @throws RequiredFieldsMissingException if any required field is missing or blank
224	     */
225	    /**
226	     * Common street-type abbreviations expanded during address normalization. Keys are the
227	     * upper-cased abbreviation tokens; values are their canonical expansions.
228	     */
229	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
230	        "ST", "STREET",
231	        "RD", "ROAD",
232	        "AVE", "AVENUE");
233	
234	    /**
235	     * Normalizes the submitted address on create and writes the canonical value back onto the
236	     * request so it is persisted, echoed back, and used for every downstream address comparison
237	     * (household duplicate detection and the household id). The value is trimmed, internal
238	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
239	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
240	     * {@code null} address is left untouched so the required-field check can report it as missing.
241	     *
242	     * @param ownerFieldsDto the submitted owner fields
243	     */
244	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
245	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
246	    }
247	
248	    /**
249	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
250	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
251	     * expanded to its full form. A {@code null} value is returned unchanged.
252	     *
253	     * @param raw the address to canonicalize, possibly {@code null}
254	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
255	     */
256	    private static String normalizeAddress(String raw) {
257	        if (raw == null) {
258	            return null;
259	        }
260	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
261	        if (collapsed.isEmpty()) {
262	            return collapsed;
263	        }
264	        String[] tokens = collapsed.split(" ");
265	        StringBuilder sb = new StringBuilder(collapsed.length());
266	        for (int i = 0; i < tokens.length; i++) {
267	            if (i > 0) {
268	                sb.append(' ');
269	            }
270	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
271	        }
272	        return sb.toString();
273	    }
274	
275	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
276	        List<String> errors = new ArrayList<>();
277	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
278	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
279	        requireText("address", ownerFieldsDto.getAddress(), errors);
280	        requireText("city", ownerFieldsDto.getCity(), errors);
281	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
282	        if (!errors.isEmpty()) {
283	            throw new RequiredFieldsMissingException(errors);
284	        }
285	    }
286	
287	    private static void requireText(String field, String value, List<String> errors) {
288	        if (value == null || value.isBlank()) {
289	            errors.add(field);
290	        }
291	    }
292	
293	    /**
294	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
295	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
296	     * and echoed back in that form.
297	     *
298	     * @param ownerFieldsDto the submitted owner fields
299	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
300	     *                                        valid E.164 number
301	     */
302	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
303	        String e164 = toE164(ownerFieldsDto.getTelephone());
304	        if (e164 == null) {
305	            throw new RequiredFieldsMissingException(List.of("telephone"));
306	        }
307	        ownerFieldsDto.setTelephone(e164);
308	    }
309	
310	    /**
311	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
312	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
313	     * and country code are present they are kept; otherwise country code {@code '+61'} is
314	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
315	     * must contain 8 to 15 digits after the {@code '+'}.
316	     *
317	     * @param raw the submitted telephone, possibly {@code null}
318	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
319	     */
320	    private static String toE164(String raw) {
321	        if (raw == null) {
322	            return null;
323	        }
324	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
325	        String digits;
326	        if (cleaned.startsWith("+")) {
327	            digits = cleaned.substring(1);
328	        } else {
329	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
330	            digits = "61" + national;
331	        }
332	        if (!digits.matches("[0-9]{8,15}")) {
333	            return null;
334	        }
335	        return "+" + digits;
336	    }
337	
338	    /**
339	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
340	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
341	     * each stored owner's telephone is normalized the same way before comparison so differing
342	     * input formats collapse to the same value.
343	     *
344	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
345	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
346	     *                                     same E.164 telephone
347	     */
348	    /**
349	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
350	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
351	     * the parts may contain whitespace or a second {@code @}.
352	     */
353	    private static final Pattern EMAIL_PATTERN =
354	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
355	
356	    /**
357	     * Normalizes the submitted email when present: the value is trimmed, required to be a
358	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
359	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
360	     *
361	     * @param ownerFieldsDto the submitted owner fields
362	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
363	     */
364	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
365	        String email = ownerFieldsDto.getEmail();
366	        if (email == null) {
367	            return;
368	        }
369	        String trimmed = email.strip();
370	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
371	            throw new InvalidEmailException(email);
372	        }
373	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
374	    }
375	
376	    /**
377	     * Defaults the registration date on create: when the client does not supply a
378	     * {@code registrationDate}, it is set to the server's current date so it is persisted
379	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
380	     *
381	     * @param ownerFieldsDto the submitted owner fields
382	     */
383	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
384	        if (ownerFieldsDto.getRegistrationDate() == null) {
385	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
386	        }
387	    }
388	
389	    /**
390	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'}
391	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
392	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
393	     * (e.g. {@code 'SMI-0007'}).
394	     *
395	     * @param owner the owner being created (with its {@code lastName} already set)
396	     */
397	    private void assignCustomerCode(Owner owner) {
398	        String lastName = owner.getLastName();
399	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
400	        int sequence = this.clinicService.findAllOwners().size() + 1;
401	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
402	    }
403	
404	    /**
405	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
406	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
407	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
408	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
409	     * canonicalized fields, every owner in the same household — including one joining an existing
410	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
411	     * order.
412	     *
413	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
414	     */
415	    private void assignHouseholdId(Owner owner) {
416	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
417	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
418	    }
419	
420	    /**
421	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
422	     * already share this owner's {@code firstName} and {@code lastName}, compared
423	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
424	     * pre-existing namesakes.
425	     *
426	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
427	     */
428	    private void assignNamesakeCount(Owner owner) {
429	        String firstName = owner.getFirstName();
430	        String lastName = owner.getLastName();
431	        long count = this.clinicService.findAllOwners().stream()
432	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
433	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
434	            .count();
435	        owner.setNamesakeCount((int) count);
436	    }
437	
438	    /**
439	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
440	     *
441	     * @param value the string to hash
442	     * @return the 64-character lower-case hex digest
443	     */
444	    private static String sha256Hex(String value) {
445	        try {
446	            byte[] digest = MessageDigest.getInstance("SHA-256")
447	                .digest(value.getBytes(StandardCharsets.UTF_8));
448	            StringBuilder sb = new StringBuilder(digest.length * 2);
449	            for (byte b : digest) {
450	                sb.append(String.format("%02x", b));
451	            }
452	            return sb.toString();
453	        }
454	        catch (NoSuchAlgorithmException e) {
455	            throw new IllegalStateException("SHA-256 not available", e);
456	        }
457	    }
458	
459	    private void rejectDuplicateTelephone(String normalizedTelephone) {
460	        boolean duplicate = this.clinicService.findAllOwners().stream()
461	            .map(Owner::getTelephone)
462	            .map(OwnerRestControllerV1::toE164)
463	            .filter(telephone -> telephone != null)
464	            .anyMatch(normalizedTelephone::equals);
465	        if (duplicate) {
466	            throw new DuplicateTelephoneException(normalizedTelephone);
467	        }
468	    }
469	
470	    /**
471	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
472	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
473	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
474	     * still counts as the same household. The check is skipped when the request opts in via
475	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
476	     * the existing one.
477	     *
478	     * @param ownerFieldsDto the submitted owner fields
479	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
480	     *                                     last name and address and the request did not opt in
481	     */
482	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
483	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
484	            return;
485	        }
486	        String lastName = collapse(ownerFieldsDto.getLastName());
487	        String address = collapse(ownerFieldsDto.getAddress());
488	        boolean duplicate = this.clinicService.findAllOwners().stream()
489	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
490	                && collapse(owner.getAddress()).equals(address));
491	        if (duplicate) {
492	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
493	        }
494	    }
495	
496	    /**
497	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
498	     * every internal run of whitespace is collapsed to a single space, and the result is
499	     * lower-cased. A {@code null} value collapses to the empty string.
500	     *
501	     * @param value the value to canonicalize, possibly {@code null}
502	     * @return the collapsed, lower-cased value
503	     */
504	    private static String collapse(String value) {
505	        if (value == null) {
506	            return "";
507	        }
508	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
509	    }
510	
511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
514	        Owner owner = this.clinicService.findOwnerById(ownerId);
515	        if (owner != null) {
516	            Pet pet = owner.getPet(petId);
517	            if (pet != null) {
518	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
519	            }
520	        }
521	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
522	    }
523	}
